const body = $input.all()[0].json?.body || $input.all()[0].json;

if (body?.data?.key?.fromMe === true) return [];
const event = (body?.event || '').toLowerCase();
if (!event.includes('upsert')) return [];

const data = body?.data || {};
const key = data?.key || {};
const msgObj = data?.message || {};
const messageType = data?.messageType || '';

const remoteJid = key?.remoteJid || '';
if (remoteJid.includes('@g.us')) return [];

let phone = remoteJid.replace('@s.whatsapp.net', '').replace(/\D/g, '');
if (!phone.startsWith('55')) phone = '55' + phone;
if (phone.length < 12) return [];

let type = 'unknown';
let text = '';

if (msgObj.conversation || msgObj.extendedTextMessage?.text) {
  type = 'text';
  text = msgObj.conversation || msgObj.extendedTextMessage?.text || '';
} else if (messageType === 'audioMessage' || messageType === 'pttMessage' || msgObj.audioMessage || msgObj.pttMessage) {
  type = 'audio';
} else if (messageType === 'imageMessage' || msgObj.imageMessage) {
  type = 'image';
  text = msgObj.imageMessage?.caption || '';
} else {
  return [];
}

if (type === 'text' && (!text || !text.trim())) return [];

const isQuizLead = type === 'text' && text.trim().startsWith('[POTENCIAL]');
let quizData = {};

if (isQuizLead) {
  const get = (label) => {
    const match = text.match(new RegExp(label + '[:\\s]+(.+)'));
    return match ? match[1].trim() : '';
  };
  quizData = {
    name:     get('Nome'),
    area:     get('Área'),
    presence: get('Presença digital'),
    revenue:  get('Faturamento'),
    captacao: get('Captação atual'),
    budget:   get('Orçamento disponível'),
  };
}

return [{
  json: {
    phone,
    message: text.trim(),
    message_type: type,
    message_key: key,
    message_key_id: key?.id || '',
    message_key_remote_jid: remoteJid,
    message_data: data,
    instance_name: body?.instance || 'vamo',
    pushName: data?.pushName || '',
    timestamp: new Date().toISOString(),
    isQuizLead,
    quizData,
  }
}];

const mediaResp = $input.first().json;
const phone = $('Parseia Mensagem Evolution').first().json.phone;
const parsed = $('Parseia Mensagem Evolution').first().json;

const extractBase64 = (resp) => resp.base64 || (resp.data && resp.data.base64) || '';
const extractMime = (resp) => (resp.mimetype || (resp.data && resp.data.mimetype) || 'audio/ogg').split(';')[0];

let base64 = extractBase64(mediaResp);
let mimetype = extractMime(mediaResp);

// Se base64 vazio, aguarda 4s e tenta novamente
if (!base64) {
  await new Promise(r => setTimeout(r, 4000));
  const retry = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://evolutionapi.viniciusguilherme.shop/chat/getBase64FromMediaMessage/vamo',
    headers: { 'apikey': $env.EVOLUTION_API_KEY, 'Content-Type': 'application/json' },
    body: {
      key: {
        id: parsed.message_key_id,
        fromMe: false,
        remoteJid: parsed.message_key_remote_jid
      }
    },
    ignoreHttpStatusErrors: true
  });
  base64 = extractBase64(retry);
  if (!mimetype || mimetype === 'audio/ogg') mimetype = extractMime(retry);
}

if (!base64) {
  return [{ json: { phone, audio_failed: true, text: '[Áudio recebido - não foi possível processar. Pode reenviar em texto?]' } }];
}

const buffer = Buffer.from(base64, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, 'audio.ogg', mimetype);

return [{ json: { phone, audio_failed: false }, binary: { audioFile: binary } }];

const input = $input.first().json;
const parsed = $('Parseia Mensagem Evolution').first().json;
const type = parsed.message_type;

let content = '';

if (type === 'text') {
  content = parsed.message;
} else if (type === 'audio') {
  content = input.text || '[Audio nao transcrito]';
} else if (type === 'image') {
  const desc = input.choices?.[0]?.message?.content || '[Imagem nao descrita]';
  content = parsed.message ? parsed.message + ' | ' + desc : desc;
}

return [{
  json: {
    phone: parsed.phone,
    content,
    message_type: type,
    is_quiz_lead: parsed.isQuizLead,
    quiz_data: parsed.quizData || {},
    instance_name: parsed.instance_name,
    pushName: parsed.pushName,
  }
}];

const raw = $input.first().json;
const pending = Array.isArray(raw) ? raw : (raw && raw.id ? [raw] : []);

if (!pending || pending.length === 0 || !pending[0]?.id) return [];

const isQuizLead = pending.some(m => m.is_quiz_lead);
const quizItem = pending.find(m => m.is_quiz_lead && m.quiz_data);
const quizData = quizItem?.quiz_data || {};

const combinedMessage = pending.map(m => {
  if (m.message_type === 'audio') return '[Audio]: ' + m.content;
  if (m.message_type === 'image') return '[Imagem]: ' + m.content;
  return m.content;
}).join('\n');

const parsedData = $('Parseia Mensagem Evolution').first().json;

return [{
  json: {
    phone: pending[0].phone,
    message: combinedMessage,
    timestamp: new Date().toISOString(),
    instance_name: parsedData.instance_name || 'vamo',
    pushName: parsedData.pushName || '',
    isQuizLead,
    quizData,
  }
}];

const raw = $input.all()[0].json;
const leads = Array.isArray(raw) ? raw : [raw];
const lead = leads[0] || {};

const incoming = $('Agrega Mensagens').first().json;

function parseHistory(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  return [];
}

const history = parseHistory(lead.sdr_history);
const alreadyHasIncoming = history.some(function(h) {
  return h && h.role === 'user' && String(h.content || '').trim() === String(incoming.message || '').trim();
});
const updatedHistory = alreadyHasIncoming
  ? history
  : [...history, { role: 'user', content: incoming.message, ts: incoming.timestamp }];

return [{
  json: {
    lead_id:          lead.id || '',
    phone:            incoming.phone,
    instance_name:    incoming.instance_name,
    business_name:    lead.business_name || incoming.quizData?.name || '',
    city:             lead.city || '',
    state:            lead.state || '',
    status:           'quiz_lead',
    isQuizLead:       true,
    quizData:         incoming.quizData,
    pushName:         incoming.pushName,
    messages:         updatedHistory.map(function(h) { return { role: h.role, content: h.content }; }),
    updated_history:  updatedHistory,
    new_user_message: incoming.message,
    google_rating:    null,
    reviews_count:    null,
    pain_signals:     lead.pain_signals || '',
  }
}];

const incomingData = $('Agrega Mensagens').first().json;
const supabaseRaw  = $input.all()[0].json;
const leads = Array.isArray(supabaseRaw) ? supabaseRaw : [supabaseRaw];
const lead  = leads[0];

if (!lead || !lead.id) return [];

function parseHistory(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  return [];
}

const history = parseHistory(lead.sdr_history);
const updatedHistory = [
  ...history,
  { role: 'user', content: incomingData.message, ts: incomingData.timestamp }
];
const messages = updatedHistory.map(function(h) {
  return { role: h.role, content: h.content };
});

return [{
  json: {
    lead_id:          lead.id,
    phone:            incomingData.phone,
    instance_name:    incomingData.instance_name,
    business_name:    lead.business_name,
    city:             lead.city,
    state:            lead.state,
    google_rating:    lead.google_rating,
    reviews_count:    lead.google_reviews_count,
    pain_signals:     lead.pain_signals,
    status:           lead.status,
    first_message:    lead.first_message,
    isQuizLead:       lead.status === 'quiz_lead',
    quizData:         {},
    pushName:         incomingData.pushName,
    messages,
    updated_history:  updatedHistory,
    new_user_message: incomingData.message,
  }
}];

const ctx = $input.all()[0].json;
const hojeISO = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const q = ctx.quizData || {};

function parseHistory(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  return [];
}

const history = parseHistory(ctx.updated_history);
const histLines = [];
for (let i = Math.max(0, history.length - 12); i < history.length; i++) {
  const h = history[i] || {};
  const label = h.role === 'assistant' ? 'SDR' : 'Lead';
  const marker = h.marker ? ' ' + h.marker : '';
  const ts = h.ts ? ' (' + String(h.ts).substring(0, 16).replace('T', ' ') + ')' : '';
  const content = String(h.content || '')
    .split('\n')
    .filter(function(line) { return !line.trim().startsWith('['); })
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 260);
  if (content) histLines.push(label + ts + marker + ': ' + content);
}
const historyText = histLines.join('\n') || '(inicio)';

const newUserMessage = String(ctx.new_user_message || ctx.message || '').trim();
const userMessages = history.filter(function(h) { return h && h.role === 'user'; });
const assistantMessages = history.filter(function(h) { return h && h.role === 'assistant'; });
const previousAssistant = assistantMessages.length ? String(assistantMessages[assistantMessages.length - 1].content || '') : '';
const firstUserMessage = userMessages.length ? String(userMessages[0].content || '') : '';
const normalizedUser = newUserMessage
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');
const normalizedAssistant = previousAssistant
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

const isQuizContext = Boolean(ctx.isQuizLead) || firstUserMessage.includes('[POTENCIAL]');
const lastAssistantAskedImplication = normalizedAssistant.includes('como voce garante') || normalizedAssistant.includes('volume previsivel');
const userAnsweredImplication = lastAssistantAskedImplication && newUserMessage && !newUserMessage.startsWith('[POTENCIAL]');
const userShowsPain = /nao garanto|nao consigo|dependo|dependencia|indicacao|indicacoes|dificuldade|por isso|quero saber|preciso|captar|clientes/.test(normalizedUser);
const shouldForcePhase2 = userAnsweredImplication || (history.length > 1 && userShowsPain);
const meetingInviteSent = normalizedAssistant.includes('reuniao') && (normalizedAssistant.includes('30') || normalizedAssistant.includes('agendar') || normalizedAssistant.includes('interesse'));
const userAcceptedMeeting = meetingInviteSent && /\b(sim|claro|ok)\b|quero|gostaria|vamos|bora|pode|tenho interesse|interesse|agendar|marcar/.test(normalizedUser);
const askedDayPeriod = normalizedAssistant.includes('qual dia') || normalizedAssistant.includes('que dia') || (normalizedAssistant.includes('manha') && normalizedAssistant.includes('tarde'));
const hasDayInCurrentMessage = /(hoje|amanha|depois de amanha|segunda|terca|ter?a|quarta|quinta|sexta|sabado|s?bado|domingo|\b\d{1,2}\/\d{1,2}\b)/.test(normalizedUser);
const hasPeriodInCurrentMessage = /(manha|manh?|tarde|noite|\d{1,2}h|\d{1,2}:\d{2})/.test(normalizedUser);
const currentMessageHasDayAndPeriod = hasDayInCurrentMessage && hasPeriodInCurrentMessage;
const userProvidedSchedulingPreference = currentMessageHasDayAndPeriod || (askedDayPeriod && (hasDayInCurrentMessage || hasPeriodInCurrentMessage));

const leadName = q.name || ctx.pushName || ctx.business_name || 'Lead';
const phoneEmail = ctx.phone + '@nexosleads.com';
const memoryFacts = [
  q.area ? 'area=' + q.area : '',
  q.presence ? 'presenca=' + q.presence : '',
  q.revenue ? 'faturamento=' + q.revenue : '',
  q.captacao ? 'captacao=' + q.captacao : '',
  q.budget ? 'orcamento=' + q.budget : '',
  ctx.status ? 'status=' + ctx.status : '',
  ctx.first_message ? 'primeira_msg=' + String(ctx.first_message).substring(0, 160) : ''
].filter(Boolean).join(' | ') || 'sem fatos estruturados';

let leadCtx;
if (isQuizContext) {
  leadCtx = 'Nome:' + leadName +
    ' Area:' + (q.area || ctx.category || 'Advocacia') +
    ' Orcamento:' + (q.budget || 'N/A') +
    ' Email:' + phoneEmail;
} else {
  const city = ctx.city ? ctx.city + (ctx.state ? '/' + ctx.state : '') : '';
  const rating = ctx.google_rating ? ' Nota:' + ctx.google_rating + '/5(' + (ctx.reviews_count || 0) + 'rev)' : '';
  const pains = ctx.pain_signals ? ' Dores:' + String(ctx.pain_signals).substring(0, 120) : '';
  leadCtx = 'Nome:' + (ctx.business_name || leadName) +
    (city ? ' Local:' + city : '') +
    rating +
    pains +
    ' Status:' + (ctx.status || 'new') +
    ' Email:' + phoneEmail;
}

const jaTemHistorico = history.length > 1;
const jaTemReuniao = ctx.status === 'meeting_scheduled';
let actionRule;
if (currentMessageHasDayAndPeriod) {
  actionRule = 'FASE_AGENDAMENTO_DIA_E_PERIODO_RECEBIDOS: A mensagem atual ja contem dia + periodo. NAO pergunte qual dia fica melhor. Chame verificarAgenda imediatamente para esse dia e periodo. Depois ofereca os horarios retornados pela ferramenta.';
} else if (userProvidedSchedulingPreference) {
  actionRule = 'FASE_AGENDAMENTO_PREFERENCIA_PARCIAL: O lead informou apenas dia OU apenas periodo. NAO reinicie o fluxo. Pergunte somente a informacao faltante.';
} else if (userAcceptedMeeting) {
  actionRule = 'FASE_AGENDAMENTO_INTERESSE_CONFIRMADO: O lead aceitou agendar a reuniao. Agora pergunte: qual dia fica melhor e se prefere manha ou tarde. NAO consulte agenda ainda se ele nao informou dia + periodo.';
} else if (shouldForcePhase2) {
  actionRule = 'FASE_ATUAL=2 OBRIGATORIO: O lead JA respondeu a pergunta de implicacao. NAO repita pergunta sobre garantir volume previsivel. Valide em 1 frase curta, conecte com o diagnostico e pergunte se ele gostaria de agendar uma reuniao de 30 minutos para ver o plano. NAO pergunte manha ou tarde ainda.';
} else if (isQuizContext && !jaTemHistorico) {
  actionRule = 'ACAO QUIZ PRIMEIRA MSG: (1) Apresente-se como Lex da Nexos. (2) Cite 1 dado do diagnostico, como area ou orcamento. (3) Faca UMA pergunta de implicacao. NAO proponha reuniao nesta mensagem.';
} else if (isQuizContext) {
  actionRule = 'ACAO QUIZ CONTINUACAO: Lead ja respondeu sondagem. Aplique FASE 2: proponha reuniao diretamente com escassez. NAO repita pergunta de implicacao.';
} else {
  actionRule = 'ACAO OUTBOUND: ' + (ctx.first_message ? 'Contexto msg enviada: ' + String(ctx.first_message).substring(0, 120) + '. ' : '') + 'Identifique a fase correta. Se e a primeira resposta do lead, aplique FASE 1. Se lead ja descreveu o desafio, aplique FASE 2. Se esta hesitando, aplique FASE 3.';
}

const systemPrompt = [
  'Voce e Lex, SDR da Nexos Group, especialista em TRAFEGO PAGO para escritorios de advocacia. HOJE:' + hojeISO + ' (BRT=UTC-3)',
  'LEAD:' + leadCtx,
  jaTemReuniao ? 'ALERTA: Lead JA TEM REUNIAO AGENDADA. NAO crie nova. Para remarcar: busca_evento_agenda -> cancela_evento_agenda -> criar_agendamento.' : '',
  'MENSAGENS_AGRUPADAS_DO_LEAD_RESPONDA_A_TODAS:' + newUserMessage,
  'MEMORIA_ESTRUTURADA:' + memoryFacts,
  'MEMORIA_RECENTE_ULTIMAS_CONVERSAS:\n' + historyText,
  '=== COMO USAR A MEMORIA ===',
  'Antes de responder, consulte MEMORIA_RECENTE_ULTIMAS_CONVERSAS e MENSAGENS_AGRUPADAS_DO_LEAD_RESPONDA_A_TODAS. Se houver varias mensagens agrupadas, interprete como uma unica intencao e responda considerando todas. Nao responda apenas a primeira mensagem.',
  'Se o lead ja respondeu uma pergunta, avance a fase. Se as mensagens agrupadas contiverem confirmacao de interesse + dia/periodo, use verificarAgenda imediatamente em vez de perguntar dia/periodo de novo.',
  '=== REGRA DE AVANCO DE FASE ===',
  shouldForcePhase2 ? 'A FASE ATUAL E 2. O lead respondeu a implicacao. PROIBIDO repetir: como voce garante volume previsivel de clientes novos por mes?' : '',
  'Se o historico ja tiver uma pergunta feita pelo SDR, NUNCA faca a mesma pergunta novamente.',
  '=== REGRAS ABSOLUTAS ===',
  '1. NUNCA sugira trafego organico, SEO, marketing de conteudo, parcerias ou qualquer alternativa. A Nexos vende EXCLUSIVAMENTE trafego pago.',
  '2. NUNCA explique como trafego pago funciona. Estrategia e o que acontece NA REUNIAO, nao no WhatsApp.',
  '3. NUNCA faca mais de 1 pergunta por mensagem.',
  '4. MAX 4 linhas. Tom direto e casual, sem formalismo.',
  '5. NUNCA pergunte pode?. Voce PODE perguntar se o lead tem interesse em agendar uma reuniao de 30 minutos, mas somente na FASE 2. So pergunte dia/periodo depois que ele confirmar interesse.',
  '=== FLUXO (siga a FASE correta baseado no historico) ===',
  'FASE 1 - PRIMEIRA RESPOSTA: Reconheca o contexto deles em 1 linha. Faca 1 pergunta de IMPLICACAO sobre o impacto real de nao ter trafego pago. Ex: Com a dependencia so de indicacao, como voce garante um volume previsivel de clientes novos por mes?',
  'FASE 2 - LEAD RESPONDEU A IMPLICACAO: Valide em 1 frase curta e convide para uma reuniao de 30 minutos. Pergunte se ele gostaria/tem interesse em agendar. NAO pergunte manha/tarde nesta mensagem. Ex: Faz sentido. Essa falta de previsibilidade e exatamente o ponto que analisamos no diagnostico. Gostaria de agendar uma reuniao de 30 minutos pra eu te mostrar um plano de escala?',
  'FASE 3 - OBJECAO OU HESITACAO: Nao rebata a objecao. Reconheca em 1 frase e refaca a proposta com dia e horario especifico. Ex: Entendo. Que tal quarta as 14h? Sao so 15 minutos e voce sai com clareza do que fazer.',
  actionRule,
  '=== FLUXO AGENDAMENTO (quando lead aceita, siga EXATAMENTE) ===',
  'PASSO 1 - Primeiro convide para uma reuniao de 30 minutos e pergunte se o lead tem interesse em agendar. Se ele confirmar interesse, pergunte UMA UNICA VEZ qual dia fica melhor e qual periodo prefere, manha ou tarde. Se a mensagem atual JA contem DIA e PERIODO, va DIRETO ao PASSO 2 SEM perguntar novamente.',
  'PASSO 2 - Lead informou DIA + PERIODO nesta msg ou no historico: chame verificarAgenda IMEDIATAMENTE. Exemplo: se ele disser amanha de manha, NAO pergunte dia novamente. Converta dia relativo: amanha=HOJE+1dia, depois de amanha=HOJE+2dias. Manha=slots antes de 12h BRT, tarde=slots a partir de 12h BRT. Apresente SOMENTE os 2 primeiros slots do periodo.',
  'PASSO 3 - Se verificarAgenda retornar qualquer opcao de horario, trate como disponibilidade real: apresente exatamente 2 opcoes e pergunte qual prefere. NAO diga que nao temos horario quando a ferramenta trouxe opcoes. So diga que nao encontrou horarios se a ferramenta nao trouxer nenhuma opcao.',
  'PASSO 4 - Lead confirma horario exato: converta BRT->UTC (+3h). Ex: 14h BRT hoje=' + hojeISO + ' -> start=' + hojeISO + 'T17:00:00Z. Chame criar_agendamento com name=' + leadName + ' email=' + phoneEmail,
  'PASSO 5 - BOOKING_OK no retorno: confirme o horario ao lead e use [STATUS:meeting_scheduled].',
  'CANCELAR/REMARCAR: busca_evento_agenda -> cancela_evento_agenda(uid) -> so entao criar novo.',
  'FIM DE CADA MENSAGEM: [STATUS:frio|morno|quente|perdido|meeting_scheduled] [FOLLOWUP:N]'
].filter(Boolean).join('\n');

const result = Object.assign({}, ctx, {
  system_prompt: systemPrompt,
  new_user_message: newUserMessage,
  updated_history: history
});
return [{ json: result }];

const agentOutput = $input.first().json.output || '';
const ctx = $('Prepara Contexto Agente').item.json;

function parseHistory(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  return [];
}

// Captura STATUS e FOLLOWUP em qualquer formato: separados ou combinados com |
const statusMatch = agentOutput.match(/\[STATUS:([\w]+)/);
const followupMatch = agentOutput.match(/FOLLOWUP:([\w]+)\]/);
const newStatus = statusMatch ? statusMatch[1] : null;
const followupDays = followupMatch ? (parseInt(followupMatch[1]) || null) : null;

// Remove qualquer bloco [...] que contenha STATUS ou FOLLOWUP
const visibleMsg = agentOutput
  .replace(/\[[^\]]*(?:STATUS|FOLLOWUP)[^\]]*\]/g, '')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const markerLine = [
  statusMatch ? '[STATUS:' + statusMatch[1] + ']' : '',
  followupMatch ? '[FOLLOWUP:' + followupMatch[1] + ']' : ''
].filter(Boolean).join(' ');

const baseHistory = parseHistory(ctx.updated_history);
const updatedHistory = [
  ...baseHistory,
  { role: 'assistant', content: visibleMsg, ts: new Date().toISOString(), marker: markerLine }
].slice(-40);

return [{
  json: {
    lead_id:         ctx.lead_id,
    phone:           ctx.phone,
    instance_name:   ctx.instance_name,
    visible_message: visibleMsg,
    marker:          markerLine,
    new_status:      newStatus,
    followup_days:   followupDays,
    updated_history: updatedHistory,
    current_status:  ctx.status,
  }
}];

const resp = $('Processa Resposta Agente').item.json;
const body = {
  sdr_history: resp.updated_history,
  status: resp.new_status || resp.current_status,
  last_reply_at: new Date().toISOString(),
};
if (resp.current_status === 'sent' || resp.current_status === 'quiz_lead') {
  body.first_reply_at = new Date().toISOString();
}
if (resp.followup_days) {
  body.next_followup_at = new Date(Date.now() + resp.followup_days * 86400000).toISOString();
}
return [{ json: Object.assign({}, resp, { patch_body: body }) }];

const raw = $input.first().json;
const pending = Array.isArray(raw) ? raw : (raw && raw.id ? [raw] : []);
if (!pending.length) return [];

const parsed = $('Parseia Mensagem Evolution').first().json;
const currentContent = String($('Prepara Conteudo Pendente').first().json.content || '').trim();
const currentType = $('Prepara Conteudo Pendente').first().json.message_type || '';

const newest = pending[pending.length - 1] || {};
const newestContent = String(newest.content || '').trim();
const newestType = newest.message_type || '';

// Cada mensagem recebida inicia uma execucao. Apenas a execucao da mensagem mais recente continua;
// execucoes anteriores param para permitir agrupar bursts como "sim" + "amanha de manha".
const isLatestExecution = newestContent === currentContent && newestType === currentType;
if (!isLatestExecution) return [];

return [{ json: { phone: parsed.phone, pending_count: pending.length, latest_content: newestContent } }];
